import hashlib
rows_per_day = {"FC-대구": 900_000, "FC-이천": 300_000, "FC-작은곳": 20_000}
for fc, n in rows_per_day.items():
    print(f"키=센터 {fc}: {n * 30:,}행 / 키=(센터,날짜,시간): 약 {n // 24:,}행")
nodes = [0] * 4
for fc in rows_per_day:
    for day in range(30):
        for hour in range(24):
            k = f"{fc}|{day}|{hour}".encode()
            nodes[int(hashlib.md5(k).hexdigest(), 16) % 4] += 1
print("노드별 파티션 수:", nodes)
# 키=센터 FC-대구: 27,000,000행 / 키=(센터,날짜,시간): 약 37,500행
# 키=센터 FC-이천: 9,000,000행 / 키=(센터,날짜,시간): 약 12,500행
# 키=센터 FC-작은곳: 600,000행 / 키=(센터,날짜,시간): 약 833행
# 노드별 파티션 수: [513, 536, 543, 568]
